// rootOpenFileNolog is Root.OpenFile.
func rootOpenFileNolog(root *Root, name string, flag int, perm FileMode) (*File, error) {
	fd, err := doInRoot(root, name, doInRootNoHandleTerminalSlash, nil, func(parent syscall.Handle, name string, endsInSlash bool) (syscall.Handle, error) {
		if endsInSlash {
			flag |= windows.O_DIRECTORY
		}
		return openat(parent, name, uint64(flag), perm)
	})
	if err != nil {
		return nil, &PathError{Op: "openat", Path: name, Err: err}
	}
	nonblocking := flag&windows.O_FILE_FLAG_OVERLAPPED != 0
	return newFile(fd, joinPath(root.Name(), name), kindOpenFile, nonblocking), nil
}

func openat(dirfd syscall.Handle, name string, flag uint64, perm FileMode) (syscall.Handle, error) {
	h, err := windows.Openat(dirfd, name, flag|syscall.O_CLOEXEC|windows.O_NOFOLLOW_ANY, syscallMode(perm))
	if err == syscall.ELOOP || err == syscall.ENOTDIR {
		if link, err := readReparseLinkAt(dirfd, name); err == nil {
			return syscall.InvalidHandle, errSymlink(link)
		}
	}
	return h, err
}

func readReparseLinkAt(dirfd syscall.Handle, name string) (string, error) {
	objectName, err := windows.NewNTUnicodeString(name)
	if err != nil {
		return "", err
	}
	objAttrs := &windows.OBJECT_ATTRIBUTES{
		ObjectName: objectName,
	}
	if dirfd != syscall.InvalidHandle {
		objAttrs.RootDirectory = dirfd
	}
	objAttrs.Length = uint32(unsafe.Sizeof(*objAttrs))
	var h syscall.Handle
	err = windows.NtCreateFile(
		&h,
		windows.FILE_GENERIC_READ,
		objAttrs,
		&windows.IO_STATUS_BLOCK{},
		nil,
		uint32(syscall.FILE_ATTRIBUTE_NORMAL),
		syscall.FILE_SHARE_READ|syscall.FILE_SHARE_WRITE|syscall.FILE_SHARE_DELETE,
		windows.FILE_OPEN,
		windows.FILE_SYNCHRONOUS_IO_NONALERT|windows.FILE_OPEN_REPARSE_POINT,
		nil,
		0,
	)
	if err != nil {
		return "", err
	}
	defer syscall.CloseHandle(h)
	return readReparseLinkHandle(h)
}

func rootOpenDir(parent syscall.Handle, name string) (syscall.Handle, error) {
	h, err := openat(parent, name, syscall.O_RDONLY|syscall.O_CLOEXEC|windows.O_DIRECTORY, 0)
	if err == syscall.ERROR_FILE_NOT_FOUND {
		// Windows returns:
		//   - ERROR_PATH_NOT_FOUND if any path compoenent before the leaf
		//     does not exist or is not a directory.
		//   - ERROR_FILE_NOT_FOUND if the leaf does not exist.
		//
		// This differs from Unix behavior, which is:
		//   - ENOENT if any path component does not exist, including the leaf.
		//   - ENOTDIR if any path component before the leaf is not a directory.
		//
		// We map syscall.ENOENT to ERROR_FILE_NOT_FOUND and syscall.ENOTDIR
		// to ERROR_PATH_NOT_FOUND, but the Windows errors don't quite match.
		//
		// For consistency with os.Open, convert ERROR_FILE_NOT_FOUND here into
		// ERROR_PATH_NOT_FOUND, since we're opening a non-leaf path component.
		err = syscall.ERROR_PATH_NOT_FOUND
	}
	return h, err
}

func rootStat(r *Root, name string, lstat bool) (FileInfo, error) {
	var flags uint
	if lstat {
		// Follow symlinks in the last path component when the path
		// ends with a path separator.
		//
		// This is not the usual behavior for Windows path resolution,
		// but empirically os.Lstat behaves this way.
		flags = doInRootAlwaysResolveTerminalSlash
	}
	fi, err := doInRoot(r, name, flags, nil, func(parent syscall.Handle, n string, endsInSlash bool) (FileInfo, error) {
		fd, err := openat(parent, n, windows.O_FILE_FLAG_OPEN_REPARSE_POINT, 0)
		if err != nil {
			return nil, err
		}
		defer syscall.CloseHandle(fd)
		fi, err := statHandle(name, fd)
		if err != nil {
			return nil, err
		}
		if !lstat && fi.(*fileStat).isReparseTagNameSurrogate() {
			link, err := readReparseLinkHandle(fd)
			if err != nil {
				return nil, err
			}
			return nil, errSymlink(link)
		}
		return fi, nil
	})
	if err != nil {
		return nil, &PathError{Op: "statat", Path: name, Err: err}
	}
	return fi, nil
}

content.text:
Agreed — an allowlist is the right shape, and I'd take it over the GOOS-split reparse-tag lookup I proposed. It states the invariant positively ("these are Entire's own files and directories"), needs no syscall and no platform split, and closes the junction gap as a side effect rather than as a special case.

Two things it changes that are worth deciding deliberately, and one carve-out.

**It also catches the FIFO, which today is a documented non-goal.** `entiredir.go:93-96` and the CLAUDE.md non-goals paragraph both say a FIFO at `.entire/settings.json` is deliberately left alone as "a hang rather than a redirection". Rejecting it is strictly better — an unkillable settings read becomes a clear error — but the doc currently asserts the opposite, so both have to move with the code.

**Nothing legitimate needs another type.** The one-level entries are `tmp/`, `metadata/`, `logs/`, `settings.json`, `settings.local.json` (`paths.go:19-21`), and there is no `Mkfifo` or `net.Listen("unix", …)` anywhere in the tree. So the allowlist costs us nothing today.

## The carve-out: `ModeIrregular`

Every other type bit is unambiguous. `ModeIrregular` is Go's "no category for this" bucket, and Windows overloads it — the `default:` arm at `types_windows.go:227` catches junctions *and* OneDrive Files On-Demand placeholders *and* every future reparse tag, identically. So a blanket reject makes a dehydrated `.entire/settings.json` in a OneDrive-synced repo a hard failure on every command, with a remedy ("replace it with a real file or directory") the user cannot act on.

And I'll downgrade my own alarm from the last message: **git cannot check out a junction.** There's no tree-object mode for one, and Git for Windows checks out symlinks, not junctions. So planting a junction requires local code execution, whereas the symlink case arrives by `git clone`. A cloud placeholder, meanwhile, requires only that the user keeps their repo in OneDrive. The asymmetry runs the wrong way for rejecting irregular by default.

So:

```go
// Entire's own entries are regular files and directories; anything else is
// something we did not put there. ModeIrregular is the deliberate exception:
// Windows reports NTFS junctions and OneDrive placeholders through the same
// bit (types_windows.go, the reparse default arm), and a checkout cannot
// produce a junction while a synced folder produces placeholders on its own.
func unsupportedEntryType(t fs.FileMode) bool {
	return t&(fs.ModeSymlink|fs.ModeNamedPipe|fs.ModeSocket|fs.ModeDevice) != 0
}
```

## Knock-ons

- `ErrEntireDirSymlinkedEntry` stops matching its own name. The remedy is identical for all these types, so per the "identified positively / different remedies" rule they should share one sentinel — `ErrEntireDirUnsupportedEntry` — with `SymlinkedEntryError` staying as the message variant that names the link target via `Readlink`. That sentinel is also the one `settings.readConfined` wraps, so the rename reaches `settings.go` and its CLAUDE.md paragraph.
- `describeMode` already has the vocabulary; reuse it for the entry message so `.entire` and its entries describe types the same way.
- `TestEntireDirRemedyMatchesTheCondition` needs to keep asserting the `.entire` remedy ("a real directory") and the entry remedy ("a real file or directory") don't bleed into each other.

Want me to implement this — code, tests for each rejected type, and the CLAUDE.md non-goals/sentinel paragraphs?

